detail='''<section class="case-hero"><div class="container"><a class="back-link" href="../index.html#work"><span aria-hidden="true">←</span> All projects</a><div class="case-heading"><div class="eyebrow"><span class="signal-dot"></span> PROJECT {{ p.order }} / {{ p.category_full|upper }}</div><h1>{{ p.title }}</h1><p class="case-subtitle">{{ p.subtitle }}</p><div class="case-actions"><a class="button button-accent" href="{{ github }}/{{ p.repo }}" target="_blank" rel="noopener noreferrer">View on GitHub <span>{{ arrow }}</span></a><span>{{ p.year }} / {{ p.project_type }}</span></div></div></div></section>
<section class="case-media-section"><div class="container"><div class="case-main-art"><img src="../{{ p.image }}" alt="{{ p.image_alt }}"/><span>{{ p.art_label }}</span></div></div></section>
<section class="case-body-section"><div class="container case-body-grid"><aside class="case-sidebar"><div class="sidebar-sticky"><span class="tiny-label">PROJECT AT A GLANCE</span><div class="case-facts">{% for label,value in p.facts %}<div><span>{{ label }}</span><strong>{{ value }}</strong></div>{% endfor %}</div><div class="case-tags">{% for t in p.tags %}<span>{{ t }}</span>{% endfor %}</div><div class="case-credit"><span>ATTRIBUTION</span><p>{{ p.contribution }}</p></div></div></aside><div class="case-story"><div class="case-intro">{{ p.description }}</div><div class="story-block"><span class="story-index">01 / THE CHALLENGE</span><h2>The challenge</h2><p>{{ p.challenge }}</p></div><div class="story-block"><span class="story-index">02 / THE APPROACH</span><h2>The approach</h2><p>{{ p.approach }}</p><ul>{% for item in p.details %}<li>{{ item }}</li>{% endfor %}</ul></div><div class="story-block"><span class="story-index">03 / THE OUTCOME</span><h2>The outcome</h2><p>{{ p.outcome }}</p><blockquote>{{ p.highlight }}</blockquote></div><div class="story-block"><span class="story-index">04 / SELECTED EVIDENCE</span><h2>From the project</h2><div class="case-gallery">{% for img,cap in p.media %}<figure><img src="../{{ img }}" loading="lazy" alt="{{ cap }}"/><figcaption>{{ cap }}</figcaption></figure>{% endfor %}</div></div><div class="case-note"><span>TRANSPARENCY NOTE</span><p>{{ p.note }}</p></div><div class="story-links"><h2>Explore the work</h2>{% for label,link in p.links %}<a href="{{ link }}" target="_blank" rel="noopener noreferrer"><span>{{ label }}</span><span>{{ arrow }}</span></a>{% endfor %}</div></div></div></section>
<section class="next-project"><div class="container"><div><span class="tiny-label">UP NEXT / PROJECT {{ next.order }}</span><a href="{{ next.slug }}.html">{{ next.title }} <span>{{ arrow }}</span></a></div></div></section>'''

render_card=Template(CARD)
cards='\n'.join(render_card.render(p=p,featured=(i==0),arrow=ARROW) for i,p in enumerate(PROJECTS))
page_template=Template(base)
home_template=Template(home)
content=home_template.render(cards=cards,github=GITHUB,linkedin=LINKEDIN,email=EMAIL,arrow=ARROW)
(ROOT/'index.html').write_text(page_template.render(prefix='',title='Mazen Younis — Software Developer | Embedded Systems & AI',meta_desc='Mazen Younis is a Berlin-based software developer working across embedded systems, industrial software, real-time systems and applied AI. Explore selected projects and experience.',content=content,github=GITHUB,linkedin=LINKEDIN,email=EMAIL),encoding='utf-8')
for i,p in enumerate(PROJECTS):
 nextp=PROJECTS[(i+1)%len(PROJECTS)]
 content=Template(detail).render(p=p,next=nextp,github=GITHUB,arrow=ARROW)
 html=page_template.render(prefix='../',title=p['title']+' — Mazen Younis',meta_desc=p['description'],content=content,github=GITHUB,linkedin=LINKEDIN,email=EMAIL)
 (ROOT/'projects'/f'{p["slug"]}.html').write_text(html,encoding='utf-8')
(ROOT/'README.md').write_text('''# Mazen Younis — Personal Portfolio\n\nA responsive, multi-page personal portfolio for software developer Mazen Younis, based on five documented GitHub projects and professional experience.\n\n## Run locally\n\nFrom this directory, run `python3 -m http.server 8080` and open `http://localhost:8080`. You can also open `index.html` directly. No build system, Node dependencies or API keys are needed.\n\n## Publish\n\nUpload the **contents** of this folder to a new public GitHub repository (for example `mazen-younis.github.io`) and use **Settings → Pages → Deploy from a branch → main / (root)**. The site works from a repository subpath as well because links are relative. Alternatively, drag this folder onto Netlify Drop.\n\n## Structure\n\n- `index.html` — homepage\n- `projects/` — five individual project case studies\n- `styles.css` — design system and responsive styles\n- `script.js` — navigation, filtering and micro-interactions\n- `assets/img/` — images and concept illustrations\n- `assets/cv/` — English and German CVs (provided by the site owner)\n\n## Content and limitations\n\n- The source uses real work, public GitHub URLs and the owner's CV.\n- Bachelor industrial source is deliberately **not** copied onto the website.\n- RTEMS and ESP32 public-source revisions are not asserted as newly retested.\n- The computer-vision card uses a **labelled concept illustration**, not a fake model output; actual results are linked in GitHub.\n- Ongoing Master's research is listed as work in progress.\n- The cropped hero portrait is from the GitHub-profile screenshot supplied by the site owner. Replace `assets/img/mazen-portrait.webp` with a higher-resolution portrait whenever available.\n- The site is **not published automatically**. It needs deployment using GitHub Pages or another static host.\n- External Google Fonts are optional; fallbacks are provided.\n\n## Updating projects\n\nTo change project descriptions or add future projects, edit the project definitions in `build_site.py` and run `python3 build_site.py` (requires Python 3 + Jinja2). Normal deployment does **not** require Python, Jinja2, or build steps.\n''',encoding='utf-8')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\n',encoding='utf-8')
print('Generated',len(PROJECTS),'case studies and index.html')
